DO $$
DECLARE v_page jsonb;
BEGIN
CREATE TEMP TABLE temp_import_pages (page_data jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0860000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 86, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "86", "printedPageNumber": 86, "pdfPageNumber": 469, "sequenceIndex": 76, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0860100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith—IV", "sourceIdentifier": "IV", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0860000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 86"}, {"id": "f0860100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "eminent. No doubt it is enough to offer fardh salaat properly, but is it so easy to observe it to the proper standard? Most probably, there will always be some deficiency in one respect or the other, and there is no way out to make up that deficiency except through nafl salaat.\n\nThere is another hadith which deals with this point more elaborately. It declares, \"Salaat is the foremost duty enjoined by Allah and the first thing to be presented before Allah, and the first thing to be reckoned for on the Day of Judgement. If the fardh salaat is found wanting in quality, then its deficiency will be made good through nafl salaat. The fasts of Ramadhaan will be the next to be reckoned for and any deficiency therein will be made good through nafl Fasts. Then Zakaat shall be reckoned for in a similar manner. If after adding nafl the good deeds are found heavier in the scales, the person concerned shall be sent to Paradise, otherwise he shall meet his doom in Hell.\" Such was the practice of the Prophet (Sallallaho alaihe wasallam) that when anybody embraced Islaam at his hand, the first thing he taught him was salaat.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 86"}, {"id": "f0860200-0000-4000-8000-000000000001", "structuralNodeId": "b0860100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith—IV", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 86"}, {"id": "f0860300-0000-4000-8000-000000000001", "structuralNodeId": "b0860100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن عبد الله بن قرط رضي الله عنه قال قال رسول الله ﷺ أول ما يحاسب به العبد يوم القيامة الصلاة فإن صلحت صلح سائر عمله وإن فسدت فسد سائر عمله رواه الطبراني", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 86"}, {"id": "f0860400-0000-4000-8000-000000000001", "structuralNodeId": "b0860100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abdullah bin Qurt (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying \"Salaat will be the first thing to be reckoned for on the Day of Judgement. If this is found satisfactory, then the rest of the deeds will also come out as such. If this is not so, then the remaining deeds are sure to be found wanting.\n\nHadhrat Umar (Radhiyallaho anho) during his caliphate had issued a proclamation to all the officers under him saying, \"I regard salaat as the most important duty. A person who ensures salaat is likely to observe other injunctions of Islam as well; but if he discards salaat, he will more easily damage the rest of Islaam.\"\n\nThe above saying of the Prophet (Sallallaho alaihe wasallam) and the proclamation of Hazrat Umar (Radhiyallaho anho) are also corroborated by another hadith, \"Satan", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 86"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0870000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 87, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "87", "printedPageNumber": 87, "pdfPageNumber": 470, "sequenceIndex": 77, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0870100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith V", "sourceIdentifier": "V", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0870000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}, {"id": "f0870100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "is scared of a Muslim so long as he is mindful of his salaat; but no sooner he neglects the salaat than Satan descends on him and becomes hopeful of leading him astray, and then he can easily be lured to commit more serious wrongs and major sins. This is exactly what is meant by Almighty Allah when He says,", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}, {"id": "f0870200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "إِنَّ الصَّلَاةَ تَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}, {"id": "f0870300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Lo! salaat preserveth from lewdness and inequity\" (XXIX: 45)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}, {"id": "f0870400-0000-4000-8000-000000000001", "structuralNodeId": "b0870100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith V", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}, {"id": "f0870500-0000-4000-8000-000000000001", "structuralNodeId": "b0870100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن عبد الله بن أبي قتادة رضي الله عنه قال رسول الله ﷺ أسوأ الناس سرقة الذي يسرق من صلاته قالوا يا رسول الله كيف يسرق من صلاته قال لا يتم ركوعها ولا سجودها رواه أحمد", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}, {"id": "f0870600-0000-4000-8000-000000000001", "structuralNodeId": "b0870100-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abdullah bin Abu Qataadah (Radhiyallaho anho) narrates, \"The Holy Prophet (Sallallaho alaihe wasallam) once said, ''The worst thief is one who steals from his salaat.'' The companions inquired, ''How can one steal from his salaat? O, Prophet of Allah!'' He replied, ''When one does not do his ruku and sajdah properly.''\n\nThere are many other Ahaadith conveying the same meaning. Stealing is a very disgraceful act and a thief is despised by everybody. What about a person who is declared ''the worst thief'', by no less a person than the Prophet himself?\n\nHadhrat Abu Darda (Radhiyallaho anho) narrates, \"Once the Prophet (Sallallaho alaihe wasallam) looked up towards the sky and said, ''The knowledge of Deen is soon to be taken away from this world.'' Ziyaad (Radhiyallaho anho), who was also present there inquired, ''How can the knowledge of Deen be taken away, O, Prophet of Allah (Sallallaho alaihe wasallam), when we are teaching the Qur''an to our children and this process will continue in our posterity?'' The Prophet (Sallallaho alaihe wasallam) said to him, ''Ziyaad! I always took you to be an intelligent person. Don''t you see that the Jews and the Christians are also teaching their Bibles to their children? Has this prevented", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 87"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0880000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 88, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "88", "printedPageNumber": 88, "pdfPageNumber": 471, "sequenceIndex": 78, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0880100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith—VI", "sourceIdentifier": "VI", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0880000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 88"}, {"id": "f0880100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "their deterioration?\" One of Hadhrat Abu Darda''s (Radhiyallaho anho) pupils says \"After hearing this hadith from Hadhrat Abu Darda (Radhiyallaho anho), I went to Hadhrat Ubaadah (Radhiyallaho anho) and related the hadith to him.\" He said, \"Abu Darda (Radhiyallaho anho) is quite right. May I tell you the first thing that will be taken away from this world? It is devotion in salaat. You will see that not a single person in the full congregation is saying his salaat with devotion.\" Hadhrat Huzaifah (Radhiyallaho anho), the confidante of the Prophet (Sallallaho alaihe wasallam), was also heard saying, \"Devotion in salaat shall be the first thing to disappear.\"\n\nIt is said in a hadith, \"Allah does not pay any attention to that salaat with which ruku and sajdah are not performed properly.\"\n\nAnother hadith says, \"A person has been offering salaat for sixty years, but in fact not a single salaat of his is accepted by Allah. This is because he has been careless about his ruku in some salaats and about his sajdah in others.\"\n\nA great stress is laid on the proper performance of salaat in the famous Epistles of Shaikh Ahmad Sirhindi (Rahmatullah alaih). His discourses on the subject cover a good portion of the Epistles. In one of them he writes, \"It is necessary among other things that, we should be particular about keeping the fingers of our hands together while in sajdah and separated while in ruku. These regulations are not without a purpose.\" He further writes, \"To keep our glance at the place of sajdah while standing, on our feet while in ruku, on our nose while in sajdah, and on our hands while in Qa''dah, goes a long way in keeping the desired concentration in salaat.\" When such ordinary regulations, which are only mustahab, increase the value of our salaat, you can well imagine how much benefit we shall derive if we be particular of other regulations, which are either sunnat or otherwise more important.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 88"}, {"id": "f0880200-0000-4000-8000-000000000001", "structuralNodeId": "b0880100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith—VI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 88"}, {"id": "f0880300-0000-4000-8000-000000000001", "structuralNodeId": "b0880100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عَنْ أُمِّ رُومَانَ رَضِيَ اللَّهُ عَنْهَا وَالِدَةِ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ رَآنِي أَبُو بَكْرٍ الصِّدِّيقُ رَضِيَ اللَّهُ عَنْهُ أَتَمَيَّلُ فِي صَلَاتِي فَزَجَرَنِي زَجْرَةً كِدْتُ أَنْصَرِفُ مِنْ صَلَاتِي قَالَ سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ إِذَا قَامَ أَحَدُكُمْ فِي الصَّلَاةِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 88"}]}'::jsonb);
FOR v_page IN SELECT page_data FROM temp_import_pages LOOP
  PERFORM import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, v_page);
END LOOP;
END;
$$;